// Keep finished runs of the "Jutarnje izdanje" workflow (morning edition + afternoon social posting).
return $input.first().json.workflow_runs
  .filter((r) => r.status === 'completed')
  .slice(0, 12)
  .map((r) => ({ json: { id: r.id, created: r.created_at, conclusion: r.conclusion, url: r.html_url } }));

// Read every job log, find the latest morning edition run and the latest social posting run,
// and turn the log lines into a short status per pipeline stage. Read-only: nothing is changed on GitHub.
const runs = $('Split runs').all().map((i) => i.json);
const logs = $input.all().map((i) => String(i.json.data ?? i.json.log ?? ''));

const clean = (log) => log.split('\n').map((l) => l.replace(/^\d{4}-\d{2}-\d{2}T[\d:.]+Z\s?/, '').replace(/\x1b\[[0-9;]*m/g, '').trim()).filter(Boolean);
const find = (lines, re) => lines.find((l) => re.test(l));

let morning = null;
let social = null;
runs.forEach((run, i) => {
  const lines = clean(logs[i] ?? '');
  if (!morning && lines.some((l) => /Poslato na GitHub/.test(l))) morning = { run, lines };
  if (!social && lines.some((l) => /(::group::|##\[group\])instagram/.test(l))) social = { run, lines };
});

const when = (r) => (r ? new Date(r.created).toLocaleString('en-GB', { timeZone: 'Europe/Belgrade', dateStyle: 'medium', timeStyle: 'short' }) : '—');
const stage = (ok, detail) => ({ ok, detail });

const m = morning?.lines ?? [];
const collect = find(m, /^Ukupno: \d+ vesti/);
const prices = find(m, /^Cene za .*modela/);
const written = find(m, /^Gotovo za [\d.]+ min:/);
const valid = find(m, /je ispravno\./);
const translated = find(m, /^Prevod objavljen/);
const images = find(m, /^Instagram za .*karusel/);
const videos = find(m, /^Video za \S+:/);
const pushed = find(m, /Poslato na GitHub: \w+/);
const notified = find(m, /Notifikacija poslata na/);

const morningStages = {
  'Collect news': stage(!!collect, collect ? `${collect.match(/(\d+) vesti/)[1]} stories collected from RSS, APIs and social media` : 'Not found'),
  'Track model prices': stage(!!prices, prices ? `${prices.match(/(\d+) modela/)[1]} models tracked on OpenRouter` : 'Not found'),
  'Claude writes the edition': stage(!!(written && valid), written ? written.replace(/^Gotovo za ([\d.]+) min: (\d+) vesti, (\d+) novih stvari, (\d+) radova, (\d+) ideja.*/, '$2 stories, $3 new tools, $4 papers, $5 app ideas in $1 min') : 'Not found'),
  'Translate to English': stage(!!translated, translated ? 'English edition published' : 'Translation failed or missing'),
  'Render images & videos': stage(!!(images && videos), `${images ? 'carousel + 7 stories' : 'no images'} · ${videos ? `${(videos.match(/\.mp4/g) ?? []).length} voiced Shorts` : 'no videos'}`),
  'Publish website': stage(!!pushed, pushed ? `Pushed ${pushed.match(/GitHub: (\w+)/)[1]} → Vercel deploy` : 'Not pushed'),
  'Push notification': stage(!!notified, notified ? notified.replace(/Notifikacija poslata na (\d+\/\d+) uređaja.*/, 'Sent to $1 devices') : 'Not sent yet'),
};

// Social posting: one log section per network.
const sections = {};
let current = null;
for (const l of social?.lines ?? []) {
  const g = l.match(/(?:::group::|##\[group\])(\w+)/);
  if (g) { current = g[1]; continue; }
  if (/::endgroup::|##\[endgroup\]/.test(l)) { current = null; continue; }
  if (current) (sections[current] ??= []).push(l);
}
const net = (name, key) => {
  const lines = sections[key] ?? [];
  const posted = lines.filter((l) => /^Objavljen/.test(l));
  const already = lines.filter((l) => /već/i.test(l)).length;
  const failed = lines.filter((l) => /nije uspeo|nije objavljen|Error:/.test(l));
  const quota = lines.some((l) => /quota/i.test(l));
  const parts = [];
  if (posted.length) parts.push(`${posted.length} published`);
  if (already) parts.push(`${already} already online`);
  if (quota) parts.push('daily quota reached, rest goes tomorrow');
  if (failed.length && !quota) parts.push(`${failed.length} failed`);
  return stage((posted.length || already) && !(failed.length && !quota), parts.join(' · ') || 'Nothing published');
};
const socialStages = {
  Instagram: net('Instagram', 'instagram'),
  Threads: net('Threads', 'threads'),
  YouTube: net('YouTube', 'youtube'),
  Telegram: net('Telegram', 'telegram'),
};

return [{
  json: {
    morning: { started: when(morning?.run), url: morning?.run.url ?? null, result: morning?.run.conclusion ?? 'not found', stages: morningStages },
    social: { started: when(social?.run), url: social?.run.url ?? null, result: social?.run.conclusion ?? 'not found', stages: socialStages },
  },
}];

// Status of one pipeline stage, from the latest morning edition run.
const g = $('Classify runs').first().json.morning;
const s = g.stages['Collect news'];
return [{ json: { stage: 'Collect news', status: s.ok ? '✅' : '❌', detail: s.detail, run: g.started, log: g.url } }];

// Status of one pipeline stage, from the latest morning edition run.
const g = $('Classify runs').first().json.morning;
const s = g.stages['Track model prices'];
return [{ json: { stage: 'Track model prices', status: s.ok ? '✅' : '❌', detail: s.detail, run: g.started, log: g.url } }];

// Status of one pipeline stage, from the latest morning edition run.
const g = $('Classify runs').first().json.morning;
const s = g.stages['Claude writes the edition'];
return [{ json: { stage: 'Claude writes the edition', status: s.ok ? '✅' : '❌', detail: s.detail, run: g.started, log: g.url } }];

// Status of one pipeline stage, from the latest morning edition run.
const g = $('Classify runs').first().json.morning;
const s = g.stages['Translate to English'];
return [{ json: { stage: 'Translate to English', status: s.ok ? '✅' : '❌', detail: s.detail, run: g.started, log: g.url } }];

// Status of one pipeline stage, from the latest morning edition run.
const g = $('Classify runs').first().json.morning;
const s = g.stages['Render images & videos'];
return [{ json: { stage: 'Render images & videos', status: s.ok ? '✅' : '❌', detail: s.detail, run: g.started, log: g.url } }];

// Status of one pipeline stage, from the latest morning edition run.
const g = $('Classify runs').first().json.morning;
const s = g.stages['Publish website'];
return [{ json: { stage: 'Publish website', status: s.ok ? '✅' : '❌', detail: s.detail, run: g.started, log: g.url } }];

// Status of one pipeline stage, from the latest morning edition run.
const g = $('Classify runs').first().json.morning;
const s = g.stages['Push notification'];
return [{ json: { stage: 'Push notification', status: s.ok ? '✅' : '❌', detail: s.detail, run: g.started, log: g.url } }];

// Status of one pipeline stage, from the latest social posting run.
const g = $('Classify runs').first().json.social;
const s = g.stages['Instagram'];
return [{ json: { stage: 'Instagram', status: s.ok ? '✅' : '❌', detail: s.detail, run: g.started, log: g.url } }];

// Status of one pipeline stage, from the latest social posting run.
const g = $('Classify runs').first().json.social;
const s = g.stages['Threads'];
return [{ json: { stage: 'Threads', status: s.ok ? '✅' : '❌', detail: s.detail, run: g.started, log: g.url } }];

// Status of one pipeline stage, from the latest social posting run.
const g = $('Classify runs').first().json.social;
const s = g.stages['YouTube'];
return [{ json: { stage: 'YouTube', status: s.ok ? '✅' : '❌', detail: s.detail, run: g.started, log: g.url } }];

// Status of one pipeline stage, from the latest social posting run.
const g = $('Classify runs').first().json.social;
const s = g.stages['Telegram'];
return [{ json: { stage: 'Telegram', status: s.ok ? '✅' : '❌', detail: s.detail, run: g.started, log: g.url } }];

// One readable overview of the whole pipeline (what the canvas shows, as text).
const c = $('Classify runs').first().json;
const lines = [];
lines.push(`MORNING EDITION · ${c.morning.started} · ${c.morning.result}`);
for (const [k, s] of Object.entries(c.morning.stages)) lines.push(`${s.ok ? '✅' : '❌'} ${k}: ${s.detail}`);
lines.push('');
lines.push(`SOCIAL POSTING · ${c.social.started} · ${c.social.result}`);
for (const [k, s] of Object.entries(c.social.stages)) lines.push(`${s.ok ? '✅' : '❌'} ${k}: ${s.detail}`);
return [{ json: { overview: lines.join('\n'), morningLog: c.morning.url, socialLog: c.social.url } }];
